import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int atCount = 0;
        String s = scanner.nextLine();
        StringBuilder current = new StringBuilder();
        List<StringBuilder> res = new ArrayList<>();

        if (!s.isEmpty()) {
            current.append(s.charAt(0));
            res.add(new StringBuilder(current));
        }

        int i = 1;
        while (i < s.length()) {
            String three = "";
            String two = "";
            if (i + 2 < s.length()) {
                three = s.substring(i, i + 3);
            }
            if (i + 1 < s.length()) {
                two = s.substring(i, i + 2);
            }

            if (three.equals("dot")) {
                for (StringBuilder r : res) r.append('.');
                current.append('.');
                i += 3;
            } else if (two.equals("at")) {
                atCount++;
                for (int j = 0; j < atCount - 1; j++) {
                    res.get(j).append("at");
                }
                for (int j = atCount - 1; j < res.size(); j++) {
                    res.get(j).append('@');
                }
                current.append(s.charAt(i));
                current.append(s.charAt(i + 1));
                res.add(new StringBuilder(current));
                i += 2;
            } else {
                current.append(s.charAt(i));
                for (StringBuilder r : res) r.append(s.charAt(i));
                i++;
            }
        }

        if (!s.isEmpty()) {
            for (StringBuilder r : res) r.append(s.charAt(s.length() - 1));
        }

        Collections.sort(res, (a, b) -> a.toString().compareTo(b.toString()));
        System.out.println(res.get(0).toString());
        scanner.close();
    }
}
